-- 013_blog.sql — generated, do not edit by hand
CREATE TABLE IF NOT EXISTS blog_posts (
  id          TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  slug        TEXT UNIQUE NOT NULL,
  category    TEXT NOT NULL,
  excerpt     TEXT,
  content     TEXT NOT NULL,
  author_name TEXT DEFAULT 'Isaya Masika',
  status      TEXT DEFAULT 'published',
  created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_blog_created ON blog_posts (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_blog_status  ON blog_posts (status);

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('glassmorphism-button', 'How to Create a Glassmorphism Button Using HTML and CSS', 'glassmorphism-button', 'CSS', 'Build a glassmorphism button with backdrop blur, layered transparency and a hover lift that stays readable on any background.', '<p>Glassmorphism looks expensive and costs almost nothing: a translucent fill, a blur behind it, and a hairline border that catches the light. The part most tutorials skip is contrast — on a busy background the label quietly disappears.</p><h2>The markup</h2><pre><code>&lt;button class="glass-btn"&gt;&lt;span&gt;Get the kit&lt;/span&gt;&lt;/button&gt;</code></pre><h2>The styles that matter</h2><pre><code>.glass-btn { position: relative; padding: 14px 26px; border-radius: 14px; font: 600 15px/1 system-ui, sans-serif; color: #111827; background: rgba(255, 255, 255, 0.55); border: 1px solid rgba(255, 255, 255, 0.70); backdrop-filter: blur(14px) saturate(160%); -webkit-backdrop-filter: blur(14px) saturate(160%); box-shadow: 0 10px 30px rgba(17, 24, 39, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.90); transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease; } .glass-btn:hover { transform: translateY(-2px); background: rgba(255, 255, 255, 0.72); box-shadow: 0 16px 40px rgba(17, 24, 39, 0.18), inset 0 1px 0 #fff; }</code></pre><p>Three decisions do the work: the fill sits at 55 percent (not 20), the border is lighter than the fill so the edge reads as a highlight, and the inset top shadow fakes a bevel. If your text still washes out, raise the fill before you touch the blur radius — opacity is the free lever, blur is the expensive one.</p><h2>Make it behave</h2><pre><code>@media (max-width: 640px) { .glass-btn { padding: 12px 20px; font-size: 14px; } } @media (prefers-reduced-motion: reduce) { .glass-btn { transition: none; } .glass-btn:hover { transform: none; } }</code></pre><p>On iOS the blur is cheap; on low-end Android it can cost a frame. The rule I use: one blurred surface per screen. A hero button is fine, a grid of nine is not.</p><h2>Ship checklist</h2><ul><li>Test over both light and dark backgrounds — the border vanishes on white.</li><li>Check with reduced motion enabled; the lift should disappear, the contrast should not.</li><li>On dark themes swap the fill to <code>rgba(255,255,255,0.08)</code> and the label to <code>#f9fafb</code>.</li></ul><p>The ready-made version, hover animation included, lives in the <a href="/components">component library</a>.</p>', 'Isaya Masika', 'published', '2026-11-10');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-hover-effects', 'Five CSS Hover Effects That Do Not Feel Cheap', 'css-hover-effects', 'CSS', 'Five hover treatments that read as craft rather than gimmick: lift, ink underline, magnetic offset, reveal and restrained tilt — each with the exact CSS.', '<p>Most hover effects feel cheap because they animate the wrong property. Scaling a card to 1.15, stacking three shadows on hover, or transitioning everything with a 400ms ease turns a crisp interface into jelly. The five below all share one rule: <strong>move at most two pixels, or one line.</strong></p><h2>1. The lift</h2><pre><code>.lift { transition: transform 160ms ease, box-shadow 160ms ease; } .lift:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(17,24,39,.09); }</code></pre><p>Three pixels, not ten. The shadow carries the depth; the transform only signals direction.</p><h2>2. Ink underline</h2><pre><code>.ink { position: relative; text-decoration: none; } .ink::after { content: ""; position: absolute; left: 0; bottom: -2px; width: 100%; height: 2px; background: currentColor; transform: scaleX(0); transform-origin: left; transition: transform 220ms cubic-bezier(.2,.8,.2,1); } .ink:hover::after { transform: scaleX(1); }</code></pre><p>Scale a decoration, never the text — scaling type reflows and looks blurry mid-animation.</p><h2>3. Magnetic offset</h2><pre><code>.magnetic { transition: transform 220ms cubic-bezier(.2,.8,.2,1); } .magnetic:hover { transform: translateX(4px); }</code></pre><p>Four pixels in the direction of the arrow inside the button reads as intent. Paired with a chevron, it is the single most convincing “this is clickable” cue there is.</p><h2>4. The reveal</h2><pre><code>.reveal { overflow: hidden; } .reveal span { display: inline-block; transition: transform 260ms ease; } .reveal:hover span { transform: translateY(-2px); }</code></pre><h2>5. Restrained tilt</h2><pre><code>.tilt { transition: transform 200ms ease; } .tilt:hover { transform: rotate(-1.2deg) translateY(-2px); }</code></pre><p>One degree is craft; six degrees is a toy. Keep <code>transform-origin</code> at center and pair it with a <code>--book-depth</code>-style static shadow so the object feels like it has weight.</p><h2>The shared contract</h2><ul><li>Never transition <code>all</code>. List the properties, and keep it under 260ms.</li><li>Wrap every block in <code>@media (prefers-reduced-motion: reduce) { transform: none }</code>.</li><li>Hover states need a keyboard twin: use <code>:focus-visible</code> with the same rules.</li></ul>', 'Isaya Masika', 'published', '2026-11-11');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-localstorage-auth', 'React LocalStorage Auth: Cache the User Without Poking a Hole in Security', 'react-localstorage-auth', 'React', 'Keep the session in an HttpOnly cookie, but paint the avatar from localStorage so returning users never see a Sign in button flicker.', '<p>Every cookie-auth app hits the same 400ms: the header has no idea whether the visitor is signed in until <code>/api/auth/me</code> resolves. For that window you show either a stale “Sign in” or an empty slot. Both look broken.</p><p>The fix is not “trust localStorage”. It is: <strong>use localStorage to paint, use the cookie to decide</strong>.</p><h2>Two states, not one</h2><pre><code>{ email: "a@b.com", verified: false } // optimistic seed, paint only { email: "a@b.com", verified: true } // cookie confirmed by the server</code></pre><p>The optimistic copy renders the avatar and greeting. It must not unlock downloads, paid content, or anything the API would refuse anyway.</p><h2>Reading the seed safely</h2><pre><code>const SEED_KEY = "stea_user"; function readSeed() { try { const raw = localStorage.getItem(SEED_KEY); if (!raw) return null; const p = JSON.parse(raw); return p?.email ? { email: p.email, verified: false } : null; } catch { return null; } }</code></pre><p>Corrupted values must degrade to signed-out. Never let <code>JSON.parse</code> throw inside render.</p><h2>Verify in the background, downgrade only on a definitive answer</h2><pre><code>useEffect(() =&gt; { let dead = false; fetch("/api/auth/me", { credentials: "include" }) .then(async (res) =&gt; { if (dead) return; const body = await res.json().catch(() =&gt; null); if (!body?.email) { localStorage.removeItem(SEED_KEY); setUser(null); return; } localStorage.setItem(SEED_KEY, JSON.stringify({ email: body.email })); setUser({ email: body.email, verified: true }); }) .catch(() =&gt; { /* offline: keep the seed, retry later */ }); return () =&gt; { dead = true; }; }, []);</code></pre><p>That catch is the whole trick. Treating a 500 or a dropped connection as “logged out” is how you kick people out on the subway.</p><h2>Do not mix the two keys</h2><p>Keep <code>stea_user</code> (server truth) and <code>stea_last_email</code> (what the human typed last time) separate. Conflating them means a failed login pre-fills a form with an address that was never verified.</p>', 'Isaya Masika', 'published', '2026-11-12');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('sticky-tailwind-navbar', 'A Sticky Navbar That Survives Mobile Without a Hamburger', 'sticky-tailwind-navbar', 'Tailwind', 'Sticky headers break on small screens because of three things: scroll anchoring, safe-area insets and a menu that fights the layout.', '<p>A sticky header is three lines of CSS. Keeping it usable on a 375px phone is the hard part, and almost every failure traces back to one of the same three causes.</p><h2>Cause 1 — the header scrolls away, then jumps back</h2><pre><code>&lt;header style="position: sticky; top: 0; z-index: 40;"&gt;</code></pre><p><code>position: sticky</code> silently does nothing if any ancestor sets <code>overflow: hidden</code> or <code>overflow: auto</code>. On phones, a card or a hero with <code>overflow-x: hidden</code> (added to kill horizontal scroll) is the usual culprit. Remove the overflow from ancestors, not from the header.</p><h2>Cause 2 — the notch</h2><pre><code>padding-top: env(safe-area-inset-top); padding-left: max(16px, env(safe-area-inset-left)); padding-right: max(16px, env(safe-area-inset-right));</code></pre><p>Without the safe-area insets the logo sits under the notch on landscape. This is a two-line fix that most tutorials skip entirely.</p><h2>Cause 3 — the menu that fights the layout</h2><p>On a phone you rarely have room for six tabs. Two options that actually work:</p><ul><li><strong>Collapse to the three most used</strong> and send the rest to the footer. This is what we do on SteaCode: Icons, Library and Blog stay, everything else lives in the footer.</li><li><strong>Horizontal scroll strip</strong>: <code>overflow-x: auto; scrollbar-width: none;</code> with <code>scroll-snap-type: x mandatory</code>.</li></ul><pre><code>.nav-strip { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; } .nav-strip::-webkit-scrollbar { display: none; } .nav-strip &gt; * { scroll-snap-align: start; flex: 0 0 auto; }</code></pre>', 'Isaya Masika', 'published', '2026-11-13');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('svg-path-animation', 'Animate an SVG Path Without Shipping a Motion Library', 'svg-path-animation', 'SVG', 'stroke-dasharray is the only trick you need to draw an icon line by line. Here is the exact maths, plus how to make it replay on hover.', '<p>The “drawing” effect you see in good icon sets is not a Lottie file. It is one CSS property pair: <code>stroke-dasharray</code> and <code>stroke-dashoffset</code>.</p><h2>The mechanism</h2><p>Give a path a dash as long as the path itself, then shift the dash out of view. Animating the offset back to zero draws the line from start to end.</p><pre><code>.draw { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; } @keyframes draw { to { stroke-dashoffset: 0; } }</code></pre><h2>Where <code>--len</code> comes from</h2><p>Hardcoding <code>1000</code> works because a dash longer than the path still renders fully — but the animation then spends most of its duration doing nothing if the real length is 300. Measure it once:</p><pre><code>const path = document.querySelector("#arc"); const len = path.getTotalLength(); path.style.setProperty("--len", len);</code></pre><h2>Replay on hover</h2><pre><code>.icon:hover .draw { animation: none; stroke-dashoffset: var(--len); animation: draw 900ms ease-out forwards; }</code></pre><p>The <code>animation: none</code> line is the important half — without it, re-adding the same animation name does nothing.</p>', 'Isaya Masika', 'published', '2026-11-14');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('core-web-vitals-lcp', 'Fix Largest Contentful Paint Before You Add Another Dependency', 'core-web-vitals-lcp', 'Performance', 'LCP is usually three things: an unprioritised hero image, a blocking font, and a JavaScript bundle that hydrates before the paint.', '<p>Most “our site is slow” tickets resolve to one of three causes, and none of them is the framework. Measure first — everything below is guesswork until you have the number.</p><h2>Measure in the field, not the lab</h2><pre><code>new PerformanceObserver((list) =&gt; { for (const e of list.getEntries()) console.log(e.startTime, e.element); }).observe({ type: "largest-contentful-paint", buffered: true });</code></pre><p>Lab tools run on fast hardware with a warm cache. A 1.2s lab LCP is routinely 3.5s on a mid-range Android over 4G. Trust the field number.</p><h2>Cause 1 — the hero image is not prioritised</h2><pre><code>&lt;img src="/hero.webp" width="1600" height="900" fetchpriority="high" decoding="async" alt=""&gt;</code></pre><p>Without <code>fetchpriority="high"</code> the image competes with the JS bundle for bandwidth and loses. Convert to WebP/AVIF first: a 240KB JPEG is often 60KB as WebP, which is a bigger win than any code change.</p><h2>Cause 2 — the font blocks the first paint</h2><pre><code>@font-face { font-family: "Inter"; src: url("/inter.woff2") format("woff2"); font-display: swap; unicode-range: U+0000-00FF; }</code></pre><p><code>font-display: swap</code> lets text paint immediately in a fallback face. Pair it with a preload <strong>only for the one weight you actually use</strong>; preloading four weights is slower than not preloading at all.</p><h2>Cause 3 — hydration runs before the paint</h2><p>If the bundle is over ~200KB gzipped, split the route. A 1.2MB single chunk means the browser parses and executes before it can paint anything interactive:</p><pre><code>const Home = lazy(() =&gt; import("./SteaCodeHomeV2"));</code></pre><p>Then confirm the split happened — in the build output, the entry chunk should stay small and the feature chunk should carry the weight.</p>', 'Isaya Masika', 'published', '2026-11-15');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('container-queries-inline-size', 'Container Queries: Style a Component by Its Slot, Not the Viewport', 'container-queries-inline-size', 'CSS', 'A card in a 280px sidebar and the same card on a 1440px hero need different layouts. Container queries let one component answer that.', '<p>Media queries ask "how wide is the browser?". That is the wrong question for a component. A product card in a 280px sidebar and the same card in a 900px hero should not share a breakpoint.</p><h2>Declare a query container</h2><pre><code>.card-slot { container-type: inline-size; container-name: card; }</code></pre><p><code>inline-size</code> makes the element a query container measured on its inline axis. That is the whole setup.</p><h2>Query the container, not the screen</h2><pre><code>@container card (min-width: 420px) { .card { display: grid; grid-template-columns: 160px 1fr; gap: 20px; } } @container card (max-width: 419px) { .card { display: block; } }</code></pre><p>Now the layout follows the slot. Resize the sidebar and the card reflows without a resize listener.</p><h2>Units that make typography honest</h2><pre><code>.card__title { font-size: clamp(13px, 8.6cqi, 22px); }</code></pre><p><code>cqi</code> is one percent of the container''s inline size. This is exactly how the 3D book cards keep their covers readable at 390px.</p>', 'Isaya Masika', 'published', '2026-11-16');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-aspect-ratio', 'Replace the Padding-Top Hack With aspect-ratio', 'css-aspect-ratio', 'CSS', 'The 56.25% padding trick has a successor that is one property, works with flex, and does not break when you add a border.', '<p>For a decade the answer to "how do I make a box a 16:9 rectangle" was <code>padding-top: 56.25%</code> plus an absolutely positioned child. It works, and it is awful.</p><h2>The replacement</h2><pre><code>.thumb { aspect-ratio: 16 / 9; width: 100%; }</code></pre><p>One property. The height is derived from the width, content flows normally, and <code>border</code> is included in the box.</p><h2>With images, use the attributes too</h2><pre><code>&lt;img src="/cover.webp" width="800" height="1200" alt=""&gt;</code></pre><p>Always ship <code>width</code> and <code>height</code> attributes: the browser derives the ratio and reserves the box before the bytes arrive.</p><h2>Where it silently fails</h2><ul><li>Flex children with <code>align-items: stretch</code> — add <code>align-self: start</code>.</li><li>Grid tracks with a fixed height — use <code>auto</code> rows.</li><li>Parent <code>min-height</code> overrides the ratio.</li></ul>', 'Isaya Masika', 'published', '2026-11-17');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('css-clamp-fluid-type', 'Fluid Type with clamp(): A Scale That Does Not Break at 200% Zoom', 'css-clamp-fluid-type', 'CSS', 'One clamp() per heading replaces five media queries — if the min and max are in rem and the middle term only moves the middle.', '<p>Fluid typography is one line of <code>clamp()</code> per step. Done wrong it is an accessibility problem: text that only responds to viewport width ignores the user''s zoom setting.</p><h2>The safe formula</h2><pre><code>h1 { font-size: clamp(2rem, 5vw + 1rem, 3.5rem); }</code></pre><ul><li><strong>Minimum in <code>rem</code>.</strong> Respects browser base font size.</li><li><strong>Maximum in <code>rem</code>.</strong> Same reason at the other end.</li><li><strong>Only the middle term uses <code>vw</code>.</strong></li></ul><h2>The zoom trap</h2><p>At 200 percent zoom on a 1440px screen the effective viewport is 720px, so <code>vw</code> shrinks and the type with it. This is why the floor must be in <code>rem</code>.</p><pre><code>html { font-size: 100%; } h1 { font-size: clamp(1.75rem, 4vw + 0.6rem, 3.5rem); }</code></pre>', 'Isaya Masika', 'published', '2026-11-18');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('position-sticky-anatomy', 'Why position: sticky Quietly Does Nothing', 'position-sticky-anatomy', 'CSS', 'Sticky headers fail for exactly four reasons: a clipped ancestor, a missing offset, a self-scrolling parent, or a transform creating a new containing block.', '<p><code>position: sticky</code> is the only CSS feature that fails silently. Four causes cover almost every case.</p><h2>1. An ancestor clips overflow</h2><p>Any ancestor with <code>overflow: hidden</code>, <code>auto</code> or <code>scroll</code> becomes that scrollport. Fix the overflow on the ancestor instead of adding <code>position: sticky</code> to more elements.</p><h2>2. Missing or wrong offset</h2><pre><code>.topbar { position: sticky; top: 0; z-index: 40; }</code></pre><p>Without <code>top</code>, sticky has no threshold and does nothing.</p><h2>3. The parent is taller than the scroll container</h2><p>Sticky is constrained to its parent. Put the sticky element in a container that spans the section it should accompany.</p><h2>4. transform / filter / will-change create a containing block</h2><p>Any of those on an ancestor makes <code>position: fixed</code> behave like absolute and breaks sticky in subtle ways.</p>', 'Isaya Masika', 'published', '2026-11-19');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('dark-mode-semantic-tokens', 'Dark Mode Without Inverting: Semantic Tokens First', 'dark-mode-semantic-tokens', 'Design Systems', 'filter: invert(1) is a party trick that ruins images and brand colour. The durable approach is two layers: raw palette tokens, then semantic tokens.', '<p>Every dark mode attempt that starts with inverting the light theme ends in the same place: photographs turn negative, the gold accent becomes muddy purple.</p><h2>Two layers</h2><pre><code>:root { --grey-0: #ffffff; --grey-900: #111827; --gold-500: #f5b400; --surface: var(--grey-0); --text: var(--grey-900); --accent: var(--gold-500); } [data-theme="dark"] { --surface: #0b0f14; --text: #e5e7eb; --accent: #ffc43d; }</code></pre><p>Components only ever use the second layer: <code>background: var(--surface)</code>, <code>color: var(--text)</code>.</p><h2>Do not use pure black</h2><p><code>#000</code> next to <code>#fff</code> text produces halation. <code>#0b0f14</code> with <code>#e5e7eb</code> text reads calmer and keeps contrast above 12:1.</p><h2>Respect the OS, do not obey it blindly</h2><p>Three states: unset follows the OS, <code>light</code> and <code>dark</code> are explicit choices. Store the choice in <code>localStorage</code> and apply it before first paint.</p>', 'Isaya Masika', 'published', '2026-11-20');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-controlled-vs-uncontrolled', 'Controlled vs Uncontrolled Inputs: The Bug Is Usually a Missing onChange', 'react-controlled-vs-uncontrolled', 'React', 'value without onChange produces an input that cannot be typed into. defaultValue produces one React cannot read. Pick by who owns the state.', '<p>The most common React bug report reads "the input is frozen". Nine times out of ten the JSX is <code>&lt;input value={email} /&gt;</code> with no <code>onChange</code>.</p><h2>The two modes</h2><pre><code>// controlled: React owns the value &lt;input value={q} onChange={(e) =&gt; setQ(e.target.value)} /&gt; // uncontrolled: the DOM owns it &lt;input defaultValue="" ref={inputRef} /&gt;</code></pre><h2>When controlled is correct</h2><ul><li>Validation per keystroke.</li><li>Derived UI — a character counter, a preview.</li><li>Programmatic value rewriting.</li></ul><h2>When uncontrolled is correct</h2><ul><li>Large forms you only read on submit.</li><li>File inputs (cannot be controlled).</li><li>Third-party widget integration.</li></ul>', 'Isaya Masika', 'published', '2026-11-21');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('useeffect-dependencies', 'useEffect Dependencies: Stale Closures, Extra Runs, and the Ref Escape Hatch', 'useeffect-dependencies', 'React', 'A missing dependency gives you yesterday''s props. An extra one gives you an infinite loop. Both come from the same mistake.', '<p><code>useEffect</code> is hard because the dependency array compares by identity, and React hands you a new function or object on almost every render.</p><h2>Failure mode 1 — the missing dependency</h2><pre><code>useEffect(() =&gt; { fetch(''/api/blog?limit='' + limit); }, []); // limit is frozen forever</code></pre><h2>Failure mode 2 — the extra dependency</h2><pre><code>const options = { limit: 20 }; // new object each render useEffect(() =&gt; { fetchList(options); }, [options]); // infinite loop</code></pre><h2>The ref escape hatch</h2><pre><code>const cb = useRef(onAuthenticated); useEffect(() =&gt; { cb.current = onAuthenticated; }, [onAuthenticated]); useEffect(() =&gt; { fetchSession().then((email) =&gt; email &amp;&amp; cb.current({ email })); }, [open]);</code></pre>', 'Isaya Masika', 'published', '2026-11-22');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('custom-fetch-hook', 'A useFetch Hook That Handles Races, Aborts and Errors', 'custom-fetch-hook', 'React', 'The naive useEffect fetch breaks in three ways: two requests resolving out of order, a stale write after unmount, and an error swallowed into silence.', '<p>Copy-pasting <code>fetch(...).then(setData)</code> works until the user changes a filter twice quickly, then the older response lands second and wins.</p><h2>The hook</h2><pre><code>export function useFetch(url) { const [state, setState] = useState({ data: null, error: null, loading: !!url }); useEffect(() =&gt; { if (!url) return; const ctrl = new AbortController(); fetch(url, { signal: ctrl.signal }).then(async (res) =&gt; { const body = await res.json().catch(() =&gt; null); if (!res.ok) throw new Error(body?.error || ''Failed''); return body; }).then((data) =&gt; setState({ data, error: null, loading: false })).catch((err) =&gt; { if (err.name === ''AbortError'') return; setState({ data: null, error: err.message, loading: false }); }); return () =&gt; ctrl.abort(); }, [url]); return state; }</code></pre><p><code>AbortController</code> removes both the race and the write-after-unmount warning without a <code>dead</code> flag.</p>', 'Isaya Masika', 'published', '2026-11-23');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-error-boundaries', 'Error Boundaries: What They Catch and What Silently Slips Through', 'react-error-boundaries', 'React', 'An error boundary catches render errors, not rejected promises, not event handlers, not failed lazy imports at the boundary.', '<p>A single thrown error inside a component unmounts the whole tree and leaves a white screen. An error boundary turns that into a message and keeps the rest alive.</p><h2>Catch</h2><ul><li>Errors during render.</li><li>Lifecycle methods.</li><li>setState callbacks during render.</li></ul><h2>Slipped through</h2><ul><li>Rejected promises.</li><li>Event handlers.</li><li>Async callbacks and timers.</li></ul><h2>Minimal implementation</h2><pre><code>class Boundary extends React.Component { state = { error: null }; static getDerivedStateFromError(error) { return { error }; } render() { if (this.state.error) return &lt;div&gt;Something broke&lt;button onClick={() =&gt; this.setState({ error: null })}&gt;Try again&lt;/button&gt;&lt;/div&gt;; return this.props.children; } }</code></pre>', 'Isaya Masika', 'published', '2026-11-24');

INSERT OR REPLACE INTO blog_posts
  (id, title, slug, category, excerpt, content, author_name, status, created_at)
VALUES
  ('react-list-keys-reconciliation', 'List Keys Are Identity, Not an Index', 'react-list-keys-reconciliation', 'React', 'Using the array index as key works until something is removed — then every input below the deleted row loses its value.', '<p>The key warning in the console gets dismissed as pedantry. Then a row is deleted and the text the user typed two rows down disappears.</p><h2>What the key means</h2><p>React reconciles lists by key, not position. A matching key means "same element, update props". A different key means "unmount this, mount that".</p><pre><code>// index as key {rows.map((row, i) =&gt; &lt;Row key={i} data={row} /&gt;)}</code></pre><p>Delete row 2 and every subsequent row keeps its old key with new data. The row component does not remount, so its internal state stays attached to the wrong record.</p><pre><code>{rows.map((row) =&gt; &lt;Row key={row.id} data={row} /&gt;)}</code></pre><h2>The duplicate-key failure</h2><p>Duplicate keys do not throw; React silently reuses the first element, and later items update the wrong card.</p>', 'Isaya Masika', 'published', '2026-11-25');
